CREATE TABLE `nteam_academic_push_settings` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `academic_account_id` int(11) NOT NULL COMMENT '教务账号ID',
  `push_types` varchar(100) DEFAULT 'wechat' COMMENT '推送类型：wechat,email',
  `schedule_reminder_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用课程提醒',
  `schedule_reminder_time` time DEFAULT '20:00:00' COMMENT '课程提醒时间',
  `grade_notify_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用成绩通知',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学术推送设置表';

