CREATE TABLE `nteam_agreements` (
  `id` int(11) NOT NULL,
  `akey` varchar(50) NOT NULL COMMENT '协议唯一标识（英文）',
  `title` varchar(100) NOT NULL COMMENT '协议名称',
  `content` mediumtext NOT NULL COMMENT '协议正文（Markdown）',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序，越小越靠前',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=启用 0=停用',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=系统内置（不可删除）',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='协议中心内容';

