INSERT INTO `nteam_agreements` (`id`, `akey`, `title`, `content`, `sort_order`, `status`, `is_system`, `created_at`, `updated_at`) VALUES
(1, 'service', '用户服务协议', '![](https://mc.xzwmc.com/csgocs/images/hero-banner.png)\r\n# 用户服务协议\r\n\r\n**最后更新日期：2026年9月21日　生效日期：2026年9月1日**\r\n\r\n> 请您在使用本服务前，务必仔细阅读并充分理解本协议全部内容，特别是以粗体标识的免责与责任限制条款。当您注册、登录或以其他方式使用本服务，即表示您已阅读并同意本协议的全部内容。\r\n\r\n## 一、协议主体与范围\r\n\r\n1. 本协议由本平台运营者（以下简称\"我们\"）与您（以下简称\"用户\"）就本平台提供的各项服务所订立。\r\n2. 本协议适用于本小程序及配套应用（以下统称\"本服务\"）。\r\n3. 本服务为在校学生自主开发的非官方学习交流项目，与学校官方无关，仅供学习交流使用。\r\n\r\n## 二、账号注册与安全\r\n\r\n1. 您应使用真实、合法、有效的信息注册账号，并对所提供信息的真实性、合法性负责。\r\n2. 您应妥善保管账号及密码，不得将账号出借、出租、转让或与他人共享。\r\n3. 因您保管不善导致账号被他人使用而产生的损失，由您自行承担。\r\n4. 如发现账号存在异常，请及时修改密码并通过\"联系客服\"告知我们。\r\n\r\n## 三、服务内容\r\n\r\n1. 本服务提供的功能包括但不限于：教务信息查询（课表、成绩等）、宿舍电费查询与用电统计、消息订阅推送、AI 智能分析等。\r\n2. 我们可能根据实际情况调整、增加或下线部分功能，调整前将以适当方式通知。\r\n3. 部分功能需要您主动绑定教务账号、宿舍信息或订阅消息后方可使用。\r\n\r\n## 四、用户行为规范\r\n\r\n您承诺在使用本服务时遵守法律法规及学校相关规定，不得从事下列行为：\r\n\r\n- 以任何方式干扰、破坏本服务的正常运行，或非法侵入他人系统与数据；\r\n- 利用本服务查询、获取、传播非本人或未经授权的信息；\r\n- 使用外挂、脚本等自动化手段批量请求，造成服务异常；\r\n- 上传、发布违法违规、侵权或含有恶意代码的内容；\r\n- 其他违反法律法规、公序良俗或损害他人合法权益的行为。\r\n\r\n## 五、第三方数据来源\r\n\r\n1. 本服务的教务、水电等信息来源于学校公开系统，我们仅作为技术手段对其进行查询与展示。\r\n2. 为避免影响学校系统，我们可能对查询频率进行限制；如遇第三方系统故障、维护或接口变更，相关功能可能暂时不可用。\r\n3. 第三方服务的使用亦受其自身协议与隐私政策约束。\r\n\r\n## 六、知识产权\r\n\r\n1. 本服务的界面设计、图标、程序代码等知识产权归我们或相应权利人所有。\r\n2. 未经许可，您不得对本服务进行复制、修改、传播、反向工程或用于任何商业用途。\r\n\r\n## 七、免责声明与责任限制\r\n\r\n1. 本服务为非官方项目，所展示信息仅供参考，**请以学校官方渠道发布的信息为准**。\r\n2. 因不可抗力、网络故障、第三方系统异常、系统维护等原因导致服务中断或数据异常的，我们不承担相应责任。\r\n3. AI 生成内容由算法自动产生，可能存在偏差或错误，**仅供参考，不构成任何形式的承诺或专业建议**。\r\n4. 在法律允许的最大范围内，我们对因使用或无法使用本服务所产生的间接、偶然或后果性损失不承担责任。\r\n\r\n## 八、服务变更、中断与终止\r\n\r\n1. 我们有权根据运营需要变更、暂停或终止全部或部分服务。\r\n2. 您可随时通过\"账号注销\"功能申请注销账号，注销后相关服务将同步终止。\r\n3. 若您违反本协议，我们有权视情况限制或终止向您提供服务。\r\n\r\n## 九、协议的修改\r\n\r\n我们可能适时修订本协议。修订后将在本页面发布更新版本并同步更新\"最后更新日期\"；若您在协议更新后继续使用本服务，即表示您同意受修订后协议的约束。\r\n\r\n## 十、法律适用与争议解决\r\n\r\n本协议的订立、生效、履行、解释及争议解决均适用中华人民共和国法律。如发生争议，双方应友好协商解决；协商不成的，您可依法向有管辖权的人民法院提起诉讼。\r\n\r\n## 十一、联系我们\r\n\r\n如您对本协议有任何疑问、意见或投诉，可通过\"我的\"页面中的\"联系客服\"功能与我们取得联系。我们将在收到您的请求后于合理期限内予以答复。', 10, 1, 1, '2026-09-22 13:26:34', '2026-10-06 20:03:19'),
(2, 'privacy', '隐私政策', '![](https://mc.xzwmc.com/csgocs/images/hero-banner.png)\r\n# 隐私政策\r\n\r\n**最后更新日期：2026年9月21日　生效日期：2026年9月1日**\r\n\r\n> 我们深知个人信息对您的重要性，并会尽全力保护您的个人信息安全可靠。请您在使用本服务前，仔细阅读并充分理解本政策。当您勾选同意或开始使用本服务，即表示您已充分理解并同意本政策的全部内容。\r\n\r\n## 一、引言\r\n\r\n本《隐私政策》（以下简称\"本政策\"）适用于本服务。我们承诺依照《中华人民共和国个人信息保护法》《中华人民共和国网络安全法》《中华人民共和国数据安全法》等法律法规，遵循合法、正当、必要和诚信原则处理您的个人信息。\r\n\r\n## 二、我们如何收集和使用您的个人信息\r\n\r\n- **注册与登录**：您提供的手机号及经加密存储的登录密码；使用微信登录时获取的微信昵称、头像及用户唯一标识（OpenID／UnionID）。\r\n- **身份与绑定信息**：您主动绑定的学号及教务系统登录凭证（仅用于向学校教务系统发起查询）；用于电费查询的校区、楼栋、房间号及电表户号等信息。\r\n- **核心服务**：电费查询与用电统计、教务信息查询（课表／成绩等）、AI 智能分析。\r\n- **消息通知与订阅**：在您订阅后向您推送课表、成绩、电费等提醒，您可随时关闭或取消订阅。\r\n- **设备与日志**：为保障服务稳定与账号安全，可能收集设备型号、操作系统、网络类型、访问时间及必要的运行日志。\r\n\r\n本服务可能申请相册／相机、剪贴板、网络状态等权限，且仅在您主动使用对应功能时触发，您可随时在系统设置中关闭授权。\r\n\r\n## 三、我们如何使用您的个人信息\r\n\r\n1. 向您提供校园信息查询、用电统计、消息推送等核心功能；\r\n2. 验证您的身份，保障账号与数据安全；\r\n3. 改进和优化产品功能，提升服务质量与使用体验；\r\n4. 识别、预防和调查欺诈、危害安全等违法违规行为。\r\n\r\n我们遵循最小必要原则，若超出上述范围使用您的个人信息，将再次征得您的同意。\r\n\r\n## 四、我们如何共享、转让、公开披露您的信息\r\n\r\n1. 我们不会向任何第三方出售您的个人信息。仅在获得您的明确同意、为实现您所请求的服务需向学校官方系统发起查询、或依据法律法规及有权机关要求时，才可能共享必要的个人信息。\r\n2. 我们不会转让您的个人信息，除非事先取得您的明确同意或依据法律法规要求。\r\n3. 我们仅在获得您明确同意或法律法规要求的情况下公开披露您的个人信息。\r\n\r\n## 五、我们如何存储和保护您的信息\r\n\r\n1. 您的个人信息存储于中华人民共和国境内，不会传输至境外。\r\n2. 除法律法规另有规定外，我们仅在为您提供服务所必需的最短期限内保留您的信息，超期后删除或匿名化处理。\r\n3. 我们采用加密存储、传输加密、访问控制、权限管理等合理措施，防止个人信息被未经授权地访问、泄露、篡改或丢失。\r\n4. 若发生个人信息安全事件，我们将立即启动应急预案并依法及时告知您。\r\n\r\n## 六、Cookie 及同类技术\r\n\r\n为提升服务体验，我们可能使用 Cookie、本地缓存等同类技术保存您的登录状态与偏好设置。您可以通过系统设置清除本地缓存，但清除后可能需要重新登录。\r\n\r\n## 七、您的权利\r\n\r\n您对自己的个人信息依法享有查阅复制、更正补充、删除、撤回同意、注销账户、投诉举报等权利，可通过\"我的\"页面相关功能或\"联系客服\"行使上述权利。\r\n\r\n## 八、未成年人保护\r\n\r\n我们高度重视未成年人个人信息的保护。若您是未满十四周岁的儿童，请在监护人陪同下阅读本政策，并在取得监护人同意后使用本服务；若我们发现在未事先取得可证实的监护人同意的情况下收集了儿童个人信息，将尽快予以删除。\r\n\r\n## 九、第三方服务\r\n\r\n为实现微信登录、微信消息推送、AI 智能分析等功能，本服务可能接入微信开放平台及相关第三方服务。相关数据将由第三方依据其隐私政策处理，建议您在使用前查阅第三方的隐私条款。\r\n\r\n## 十、本政策的更新\r\n\r\n我们可能适时修订本政策，修订后将在本页面发布更新版本并同步更新\"最后更新日期\"；对于重大变更，我们将另行显著告知。若您在政策更新后继续使用本服务，即表示您同意受修订后政策的约束。\r\n\r\n## 十一、如何联系我们\r\n\r\n如您对本政策或个人信息处理有任何疑问、意见或投诉，可通过\"我的\"页面中的\"联系客服\"功能与我们联系，我们将在合理期限内予以答复。', 20, 1, 1, '2026-09-22 13:26:34', '2026-10-06 20:03:20'),
(3, 'cancel', '用户注销协议', '![](https://mc.xzwmc.com/csgocs/images/hero-banner.png)\r\n# 用户注销服务协议\r\n**温馨提示：在提交账号注销申请前，请您务必仔细阅读、充分理解本协议全部条款。您发起账号注销操作，即代表您已完全知晓、理解并自愿接受本协议所有规则，自愿承担注销带来的全部法律后果与风险。**\r\n## 一、注销定义与法律效力\r\n1. 账号注销是用户主动发起的、终止用户与平台全部服务关系、解除个人信息授权、销毁账号使用权限的**不可逆最终操作**。\r\n2. 账号一经正式注销生效，该账号将永久作废，用户永久丧失该账号的登录资格、使用权限、查询权限、服务权益及全部平台功能使用权。\r\n3. 账号注销成功后，**账号、数据、权益均无法恢复、无法找回、无法人工回溯、无法申诉复原**。\r\n4. 账号注销仅终止未来服务关系，**不溯及、不免除用户注销前使用服务产生的一切违规责任、法律责任、纠纷责任**。\r\n## 二、注销前置条件与禁止注销情形\r\n1. 用户申请注销，须保证账号状态正常、无异常风控、无权属争议、为本人合法持有。\r\n2. 账号存在以下任意情形的，平台有权**直接驳回注销申请、终止注销流程，且无需另行通知**：\r\n   （1）账号处于冻结、封禁、限制登录、处罚、风控拦截等异常状态；\r\n   （2）账号存在未办结投诉、举报、纠纷、申诉、核查工单；\r\n   （3）账号存在未完成业务、待审核事项、待处理订单、未履约服务；\r\n   （4）账号存在未解除的设备绑定、第三方授权、关联子账号、共享权限；\r\n   （5）系统判定账号存在被盗风险、异常登录、批量操作、恶意操作嫌疑；\r\n   （6）依据法律法规、监管要求，暂不允许注销的账号。\r\n3. 用户应在发起注销前，**自行完成全部解绑、解约、清算工作**，因用户未提前处理导致的一切问题与损失，由用户自行承担。\r\n## 三、账号资产、权益与费用清算规则\r\n1. 用户确认：注销前需自行妥善处理账号内全部个人权益，包括但不限于积分、优惠券、活动奖励、虚拟权益、专属权限、收藏内容、个性化资源等。\r\n2. 账号正式注销后，**所有未使用、未到期、未核销的权益全部自动清零、永久作废**，平台不提供退款、折现、转移、继承、补发、补偿等任何服务。\r\n3. 若账号存在未结清费用、未完成履约义务，平台有权拒绝注销申请，直至用户完全结清为止。\r\n4. 账号注销后，用户将永久丧失该账号对应的全部校园专属权益、平台福利、活动资格及个性化服务。\r\n## 四、用户数据删除、留存与隐私规则\r\n1. 账号注销生效后，平台将依据法律规定删除该账号下全部非必要用户数据，涵盖但不限于：个人资料、头像昵称、联系方式、身份信息、校园绑定信息、宿舍绑定、认证资料、第三方绑定记录、消息设置、推送配置、课程数据、成绩记录、浏览记录、操作日志、用户自主上传内容及所有个性化配置。\r\n2. 所有删除数据**永久不可恢复、不可检索、不可找回**，用户须在注销前自行完成重要数据备份，平台不承担数据留存与恢复义务。\r\n3. 为符合法律法规、安全风控、纠纷追溯、司法协查要求，平台可**有限、合规、隔离留存**必要日志数据，该类数据仅用于合规核查与安全追溯，**绝不用于商业营销、个性化推送及其他无关用途**。\r\n4. 法定留存期限届满后，平台将对留存数据进行彻底删除或匿名化、去标识化处理，使其无法关联至任何自然人用户。\r\n5. 注销完成即刻终止平台对该用户个人信息的收集、存储、使用、展示、共享行为，彻底终止全部个人信息授权关系。\r\n## 五、身份核验与安全校验规则\r\n1. 为防范盗号注销、恶意注销、冒用注销等风险，**所有注销申请必须通过平台安全核验**，未通过核验无法提交注销。\r\n2. 核验方式包括但不限于：登录密码核验、短信验证码、邮箱验证码、人机验证、设备安全校验等，具体核验项目以平台实时页面展示为准。\r\n3. 出现核验失败、信息不匹配、验证超时、设备异常、操作频繁等情况，系统可直接拦截注销流程。\r\n4. 用户不得通过破解、绕过、篡改等方式规避注销核验，一经发现，平台有权封禁账号并依法追责。\r\n## 六、注销冷静期与撤销机制\r\n1. 用户提交注销申请并通过核验后，账号自动进入**注销冷静期**，冷静期具体时长以平台页面公示为准。\r\n2. 冷静期为用户专属反悔周期，**冷静期内任意正常登录账号，即自动撤销本次注销申请**，账号恢复为正常使用状态。\r\n3. 冷静期内用户未登录、未主动撤销注销的，冷静期届满后，系统将**自动执行永久注销，操作不可逆、不可撤回**。\r\n4. 冷静期内账号仍处于正常可用状态，期间产生的一切操作、行为、记录及对应责任，均由用户本人承担。\r\n## 七、用户承诺、义务与风险自担\r\n1. 用户郑重承诺：本次注销操作系本人真实、自愿、自主的意思表示，不存在胁迫、误导、欺诈等情形。\r\n2. 用户承诺不以注销账号方式规避处罚、逃避责任、恶意套利、恶意刷取数据及实施任何违规行为。\r\n3. 用户已充分知悉并认可：账号注销属于高风险不可逆操作，数据丢失、权益清零、账号作废等全部后果与风险，**均由用户本人独立承担，平台不承担任何赔偿、补偿、恢复责任**。\r\n4. 用户保证合法持有并操作本账号，严禁注销他人账号，因恶意冒用、违规操作造成的一切损失与法律责任，由操作人自行承担。\r\n## 八、平台权利与义务\r\n1. 平台严格依照国家法律法规及本协议规则，公开、规范执行注销核验、冷静期管理、数据删除、数据留存流程。\r\n2. 平台保证注销规则、流程、时效、要求均在页面公开公示，充分保障用户知情权。\r\n3. 平台有权根据合规要求、监管政策、业务迭代优化，合理调整注销流程与协议内容，调整后公示即生效。\r\n4. 除法律明确规定情形外，平台无义务提供人工特殊注销、数据恢复、权益补回、特例处理等个性化服务。\r\n## 九、未成年人用户特别条款\r\n1. 未成年人用户申请注销账号，必须在监护人知情、同意与全程监督下进行。\r\n2. 未成年人因账号注销产生的一切后果，由本人及其法定监护人自行承担。\r\n3. 平台对未成年人相关数据严格按照《未成年人网络保护条例》执行最小化留存原则，最大限度保护未成年人隐私安全。\r\n## 十、协议效力、修订与优先级\r\n1. 本《用户注销服务协议》为平台《用户服务协议》《隐私政策》的专项附属协议，**具备同等法律效力**。\r\n2. 本协议条款如与国家法律法规强制性规定冲突，以法律法规为准，其余条款继续完全有效。\r\n3. 平台有权不定期优化、修订本协议内容，修订内容将通过平台公示，公示后立即生效，用户继续使用平台服务即视为默认接受最新协议。\r\n4. 本协议未尽事宜，依照国家法律法规及平台公开规则执行。\r\n## 十一、免责与不可抗力\r\n1. 因系统维护、版本升级、网络异常、技术故障、不可抗力、监管整改等非平台主观可控原因，导致注销流程短暂延迟、数据处理延后的，平台免于承担违约责任。\r\n2. 因用户自身操作失误、未及时备份数据、未提前解绑关联、未阅读协议规则等个人原因造成的损失，全部由用户自行承担，平台免责。\r\n## 十二、争议解决\r\n1. 因账号注销及本协议引发的争议，双方优先采取友好协商方式解决。\r\n2. 协商无法达成一致的，双方一致同意向**平台运营主体所在地有管辖权的人民法院**提起诉讼。\r\n## 十三、最终知情确认\r\n用户点击确认、勾选同意并提交注销申请，即代表：**本人已完整阅读、清晰理解、完全认可本协议全部条款，明确知晓账号注销为不可逆永久操作，自愿接受全部风险、后果与法律约束，无任何异议。**', 30, 1, 1, '2026-09-22 13:26:34', '2026-10-06 20:03:23'),
(4, 'disclaimer', '免责声明', '![](https://mc.xzwmc.com/csgocs/images/hero-banner.png)\r\n# 免责声明\r\n\r\n**最后更新日期：2026年9月21日**\r\n\r\n1. **非官方项目**：本服务由在校学生自主开发，为个人学习交流项目，**与学校官方无关**，不代表学校官方立场。\r\n2. **信息来源**：本服务展示的教务、水电等信息均来源于学校公开系统，我们仅进行技术性查询与整理，**内容仅供参考，请以学校官方发布为准**。\r\n3. **第三方系统**：如学校系统进行维护、升级或接口调整，可能导致相关功能暂时不可用或数据延迟，我们不因此承担任何责任。\r\n4. **AI 生成内容**：AI 分析结果由算法自动生成，可能存在不准确或偏差，**仅供学习参考，不构成任何专业建议或承诺**。\r\n5. **使用风险**：请您在合法合规的前提下使用本服务；因用户自身操作不当、账号保管不善或违反相关约定所产生的后果，由用户自行承担。\r\n6. **不可抗力**：因不可抗力、网络故障、黑客攻击等超出我们可控范围的原因导致的服务中断或数据丢失，我们不承担责任。\r\n7. **权益主张**：如本服务内容无意中侵犯了您的合法权益，请通过\"联系客服\"与我们联系，我们将及时核实并处理。', 40, 1, 1, '2026-09-22 13:26:34', '2026-10-06 20:03:22');

