(2, '【成绩（学期：2025-2026-2）】\n- 1+X证书模块（一）：成绩 93，学分 1，绩点 -，属性 选修\n- 软件测试技术：成绩 93，学分 4，绩点 -，属性 选修\n- Android高级开发与移动Web开发：成绩 82，学分 4，绩点 -，属性 必修\n- 微信小程序开发：成绩 84，学分 4，绩点 -，属性 选修\n- 前端框架技术：成绩 85，学分 4，绩点 -，属性 必修\n- 毛泽东思想和中国特色社会主义理论体系概论：成绩 34，学分 2，绩点 -，属性 必修\n- 体育与健康（四）：成绩 60，学分 2，绩点 -，属性 必修\n- 形势与政策（四）：成绩 83，学分 0.2，绩点 -，属性 必修\n- 走在前列的广东实践：成绩 60，学分 1，绩点 -，属性 必修\n- 就业与职场礼仪指南(公选)：成绩 81，学分 2，绩点 -，属性 公选\n\n【本周课程】\n周一：\n- 1+X证书模块（二） 第10304节 @-\n周二：\n- 大学语文 第20304节 @-\n- 移动开发项目实训 第20506节 @-\n- 移动开发项目实训 第20708节 @-\n- Linux操作系统应用 第20910节 @-\n- Linux操作系统应用 第21112节 @-\n周三：\n- 软件自动化测试 第30910节 @-\n- 软件自动化测试 第31112节 @-\n周四：\n- 就业指导 第403节 @-\n周五：\n- 计算机专业英语 第50506节 @-\n\n【学生档案】\n姓名：叶龙\n学工号：24103230122\n\n【绑定宿舍及用电】\n- 房间 11829（默认）：剩余电量 72.23 度（电量充足）\n- 房间 11879：剩余电量 218.74 度（电量充足）\n- 房间 11833【5B214】：剩余电量 220.18 度（电量充足）\n- 房间 11831【5B213】：剩余电量 174.23 度（电量充足）\n\n【宿舍用电历史（11829）】\n房间 11829：历史总用电约 1880.5 度，日均约 31.34 度（数据范围 2026-05-09 ~ 2026-09-18）\n用电最多的一天：2026-05-15，约 52.46 度\n近期每日用电趋势（末14天）：\n- 2026-09-05：约 17.17 度\n- 2026-09-06：约 40.92 度\n- 2026-09-07：约 27.86 度\n- 2026-09-08：约 24.26 度\n- 2026-09-09：约 30.83 度\n- 2026-09-10：约 30.52 度\n- 2026-09-11：约 30.83 度\n- 2026-09-12：约 33.65 度\n- 2026-09-13：约 35.6 度\n- 2026-09-14：约 29.45 度\n- 2026-09-15：约 26.18 度\n- 2026-09-16：约 35.12 度\n- 2026-09-17：约 28.94 度\n- 2026-09-18：约 36.85 度\n\n【宿舍用电历史（11833）】\n房间 11833【5B214】：历史总用电约 943.7 度，日均约 25.51 度（数据范围 2026-05-14 ~ 2026-06-24）\n用电最多的一天：2026-05-27，约 44.77 度\n近期每日用电趋势（末14天）：\n- 2026-06-11：约 20.06 度\n- 2026-06-12：约 12.42 度\n- 2026-06-13：约 13.37 度\n- 2026-06-14：约 26.51 度\n- 2026-06-15：约 19.86 度\n- 2026-06-16：约 18.18 度\n- 2026-06-17：约 11.28 度\n- 2026-06-18：约 16.77 度\n- 2026-06-19：约 16.17 度\n- 2026-06-20：约 24.88 度\n- 2026-06-21：约 32.23 度\n- 2026-06-22：约 29.09 度\n- 2026-06-23：约 28.11 度\n- 2026-06-24：约 17.51 度\n\n【宿舍用电历史（11831）】\n房间 11831【5B213】：历史总用电约 1239.3 度，日均约 39.98 度（数据范围 2026-05-14 ~ 2026-06-25）\n用电最多的一天：2026-06-02，约 226.37 度\n近期每日用电趋势（末14天）：\n- 2026-06-11：约 39.94 度\n- 2026-06-12：约 32.94 度\n- 2026-06-13：约 34.