CREATE TABLE `nteam_announcements` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL COMMENT '公告标题',
  `content` text NOT NULL COMMENT '公告内容(Markdown)',
  `thumbnail` varchar(500) DEFAULT NULL COMMENT '缩略图路径',
  `image` varchar(500) DEFAULT NULL COMMENT '大图路径',
  `is_top` tinyint(1) DEFAULT '0' COMMENT '是否置顶',
  `is_published` tinyint(1) DEFAULT '1' COMMENT '是否发布',
  `view_count` int(11) DEFAULT '0' COMMENT '浏览次数',
  `author` varchar(100) DEFAULT NULL COMMENT '作者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公告表';

--
-- 转存表中的数据 `nteam_announcements`
--

INSERT INTO `nteam_announcements` (`id`, `title`, `content`, `thumbnail`, `image`, `is_top`, `is_published`, `view_count`, `author`, `create_time`, `update_time`) VALUES
(5, '欢迎使用智校通-智慧校园，这份指南请收好！', '![logo](https://mc.xzwmc.com/csgocs/images/logo-header.png)\r\n# 欢迎使用智校通-智慧校园\r\n> 把课表、成绩、电费、通知，装进一个 App，AI赋能高效智慧校园方案。\r\n---\r\n![ffo8EytzA](https://mc.xzwmc.com/csgocs/images/hero-banner.png)\r\n## 你好，同学\r\n欢迎来到 **智慧校园**。\r\n你是不是也有过这样的日常——\r\n想查一下今天第几节课、教室里坐哪，要翻好几个网页；\r\n想知道宿舍电费还剩多少，却总在快没电时才想起来；\r\n成绩出来了、课表变了，也没人提醒你一声。\r\n我们希望把这些零碎的麻烦，收进一个清爽好用的小应用里。\r\n在这里，打开首页就能看到 **下节课** 和 **电费余额**，一条通知也不会错过。\r\n这是我们开发的校园助手，希望能让你的校园生活省一点事、多一点从容。\r\n---\r\n## 这是什么\r\n智慧校园是一款面向在校学生的 **校园信息查询与提醒工具**，主要提供：\r\n- 教务信息查询（成绩、课程表、学籍信息）\r\n- 宿舍电费查询与用电统计\r\n- 消息订阅与推送提醒\r\n- 校园通知公告（支持 AI 智能摘要）\r\n- AI 助手（对话问答与智能分析）\r\n---\r\n## 三步开始使用\r\n### 第一步：注册并登录\r\n使用优秀注册账号，或直接通过微信快捷登录。\r\n忘记密码也不怕，可通过邮箱验证码找回。\r\n### 第二步：绑定教务系统\r\n在「教务绑定」中输入学号与教务系统密码，绑定成功后即可查询成绩、课程表和学籍信息。\r\n### 第三步：绑定宿舍并开启推送\r\n在「宿舍绑定」中选择校区、楼栋与房间号，绑定后即可查询电费；\r\n再前往「电费推送设置」「学术推送设置」，开启你关心的提醒。\r\n完成这三步，首页的速览卡片就会自动为你更新啦。\r\n---\r\n## 你都能用它做什么\r\n### 首页速览，一眼掌握\r\n打开首页即可看到：\r\n- **下一节课**：课程名称、上课时间与教室，还能看到课程状态（进行中 / 即将开始 / 已结束）\r\n- **电费余额**：宿舍当前电费余额，余额偏低时会醒目提示\r\n- **通知公告**：最新的校园通知一目了然，支持置顶\r\n- 还会随机送你一句古诗词，给每天一点小小的仪式感\r\n### 教务服务\r\n绑定教务后，你可以：\r\n- **成绩查询**：按学期查看各科成绩\r\n- **我的课程表**：完整课表，支持按周查看\r\n- **今日课程**：当前星期几、第几节，一目了然\r\n- **学籍信息**：查看你的学籍基本信息\r\n### 宿舍电费\r\n绑定宿舍后，你可以：\r\n- **电费查询**：实时查看宿舍电费余额\r\n- **用电记录 / 用电统计**：根据余额变化，看看最近用了多少电、每天花了多少\r\n- **批量查询**：一次查询多个房间的电费\r\n### 消息推送与订阅\r\n- **电费推送设置**：余额不足时及时提醒，避免突然断电\r\n- **学术推送设置**：成绩发布、课表变动等消息主动通知你\r\n- **订阅管理 / 订阅历史**：随时查看和管理你的订阅，也能回顾收到过的提醒\r\n> 小提示：订阅采用微信一次性订阅消息机制，收到提醒后如需继续接收，记得在首页的提示里重新增加订阅次数。\r\n### 通知公告\r\n校园的重要通知，第一时间送达。\r\n每篇公告还可生成一份 **AI 摘要**，时间紧的时候，几秒读懂重点。\r\n### AI 助手\r\n底部「AI 助手」是你的随身小帮手：\r\n- **智能对话**：有问必答，随问随用\r\n- **智能分析**：对成绩、课表、用电情况给出通俗易懂的分析与建议\r\n### 账号与安全\r\n- 注册 / 登录 / 忘记密码 / 修改密码\r\n- **微信绑定**与**第三方账号绑定**，多种方式轻松登录\r\n- **注销账号**：如需离开，可在「注销账号」中自助办理\r\n### 更多功能\r\n- **隐私协议**：清晰了解我们如何收集与保护你的信息\r\n- **关于我们 / 更新日志**：了解项目背景与每个版本的更新内容\r\n- **联系客服**：遇到问题，随时与我们取得联系\r\n---\r\n## 你的隐私，我们认真对待\r\n- 我们仅收集为你提供服务所 **必需** 的信息\r\n- 登录凭证、密码等敏感信息均 **加密存储**\r\n- 你可以随时解绑教务 / 宿舍 / 第三方账号，或申请注销账号\r\n- 详细说明请查阅应用内的《隐私协议》\r\n---\r\n## 常见问题\r\n**Q：为什么绑定教务后查不到数据？**\r\nA：请确认学号与教务密码填写无误。若学校教务系统正在维护或更换了登录方式，可能会暂时无法查询，稍后再试或联系我们反馈。\r\n**Q：为什么电费余额和实际不一致？**\r\nA：电费数据来自学校水电系统，可能存在同步延迟，实际以学校系统为准。\r\n**Q：收不到推送怎么办？**\r\nA：请先确认已在「电费推送设置 / 学术推送设置」中开启对应提醒，并保证订阅次数充足（一次性订阅消息在收到后需重新订阅）。同时在手机系统设置中允许本应用发送通知。\r\n**Q：我不想用了，怎么注销账号？**\r\nA：进入「注销账号」，阅读并同意《用户注销服务协议》后，按引导完成身份验证即可注销。\r\n---\r\n## 联系我们\r\n如果你在使用中遇到问题，或有好的建议，欢迎通过应用内 **「我的 - 联系客服」** 与我们取得联系。\r\n你的每一条反馈，都会让它变得更好。\r\n---\r\n感谢你的使用与信任。\r\n愿它能让你的校园生活，轻松一点点。\r\n**智校通-智慧校园 · 团队**\r\n**2026年9月**', '/uploads/announcements/20260601210032_6a1d827042cba.jpg', '', 1, 1, 184, '', '2026-05-07 08:29:00', '2026-10-19 15:43:05'),
(7, '智校通电费查询功能升级，看过来！', '<p><strong>各位用户：</strong></p>\r\n<p>经过智校通技术团队的优化迭代，宿舍电费查询功能现已<span style=\"color:#2563eb; font-weight:bold;\">全新升级✨</span>，本次更新内容如下：</p>\r\n<ol>\r\n<li>新增<span style=\"color:#059669; font-weight:bold;\">逐小时电费统计</span>，可查看平均每小时用电量，用电明细一目了然；</li>\r\n<li>上线<span style=\"color:#059669; font-weight:bold;\">趣味用电账单</span>，一键解锁宿舍用电画像，快来看看你的宿舍用电情况；</li>\r\n<li>扩大覆盖范围：支持<span style=\"color:#059669; font-weight:bold;\">高州校区全部宿舍、茂名校区11‑13区宿舍</span>电费查询。</li>\r\n</ol>\r\n![261006103759_938_20](/uploads/announcements/20261006103816_6ac45f1845ac2.png)\r\n<br>\r\n<p>小程序和网页端无需升级，<span style=\"color:#2563eb; font-weight:bold;\">重新进入或刷新</span>即可体验。安卓端请更新版本至<span style=\"color:#2563eb; font-weight:bold;\">1.9.6</span>即可体验。</p>\r\n<p>若您在使用过程中遇到问题，欢迎随时联系我们获取协助。</p>\r\n<p style=\"text-align:right;\">智校通</p>\r\n<p style=\"text-align:right;\">2026.10.6</p>', '/uploads/announcements/20261006100227_6ac456b306d62.png', '', 0, 1, 37, '', '2026-10-06 10:02:34', '2026-10-19 15:42:49');

