--
-- 表的结构 `nteam_app_versions`
--

CREATE TABLE `nteam_app_versions` (
  `id` int(11) NOT NULL,
  `version` varchar(32) NOT NULL COMMENT '版本号，如 1.3.26',
  `version_code` int(11) NOT NULL DEFAULT '0' COMMENT '数字版本，用于比较大小，如 1002',
  `platform` varchar(16) NOT NULL DEFAULT 'all' COMMENT '平台：all/android/ios/harmony',
  `force_update` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否强制更新：0否 1是',
  `download_url` varchar(512) NOT NULL DEFAULT '' COMMENT '下载/更新地址（商店或 apk 直链）',
  `changelog` text COMMENT '更新日志，支持多行',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '版本开关：1已发布(上架) 0停用(下架)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='App 版本管理';

--
-- 转存表中的数据 `nteam_app_versions`
--

INSERT INTO `nteam_app_versions` (`id`, `version`, `version_code`, `platform`, `force_update`, `download_url`, `changelog`, `status`, `created_at`, `updated_at`) VALUES
(2, '0.1', 100, 'all', 0, 'https://mc.xzwmc.com/csgocs/', '首个正式内测版本\r\n \r\n- 实现平台最基础核心能力，支持账号登录\r\n- 基础页面框架搭建，课表查询基础功能可用', 1, '2026-09-22 09:59:38', '2026-09-23 11:30:03'),
(3, '1.0', 1000, 'all', 0, 'https://xiaolong666.lanzoub.com/iT4nQ49io34d&pwd=75do', '- 聚合快捷登录，支持多种第三方账号一键登录\r\n- 电费页面增加时间筛选，可以查询指定时间段用电记录\r\n- 成绩查询支持设置默认学期，打开直接加载常用学期成绩\r\n- 全局滚动条样式美化，表格分页、排序交互优化\r\n- 优化App状态栏、导航栏显示，适配深色背景；增加“回到顶部”按钮\r\n- 优化页面切换动画，低配手机运行更流畅\r\n- 修复子目录部署时公告图片无法正常显示\r\n- 修复AI按钮重复点击导致多次请求的问题', 1, '2026-09-22 10:00:44', '2026-10-05 18:15:23'),
(4, '1.2.13', 1002, 'all', 0, 'https://mc.xzwmc.com/csgocs/', '- 重磅新增【AI助手】聊天页面，底部导航新增入口，可以直接和AI对话\r\n- 课表升级：支持自定义学校作息时间，不再固定死上课时段，可适配更多院校\r\n- 课程点击弹出详情窗口，直接查看课程信息，不用跳转新页面\r\n- 支持QQ、微信等第三方账号快捷登录、账号绑定/解绑\r\n- 新增订阅消息历史记录，你可以查看以往收到的推送通知\r\n- 页面新增悬浮AI快捷按钮，大部分页面随时可以唤起AI分析\r\n- 头像上传功能优化，保存更稳定\r\n- 登录页优化，第三方登录图标更好看\r\n- 修复课表节次计算、横向滚动适配问题', 1, '2026-09-22 10:01:09', '2026-09-22 10:01:09'),
(5, '1.3.25', 1003, 'all', 0, 'https://xiaolong666.lanzoub.com/iv75949io0bc&pwd=60zx', '- 全平台上线AI智能分析：课表、成绩、宿舍电费都可以一键AI解读\r\n- AI分析结果会自动缓存，减少等待，避免重复请求\r\n- 新增平台维护模式，区分日常维护和临时停机维护提示\r\n- 首页轮播图自定义管理，管理员可以后台更换首页大图\r\n- 优化网页部署兼容性，修复图片、头像加载出错问题\r\n- 优化小程序返回页面的交互逻辑\r\n- 修复部分环境下文件、头像路径加载错误', 1, '2026-09-22 10:01:36', '2026-09-22 15:15:57'),
(6, '1.6.10', 1006, 'all', 0, 'https://mc.xzwmc.com/csgocs/', '- 公告支持AI智能摘要，长公告自动提炼重点内容\r\n- 版本更新日志页面上线，可以在这里查看所有历史更新记录\r\n- 后台支持管理App版本，新增自动检测更新、手动检查更新功能\r\n- AI摘要界面优化，新增图标和提示文字，阅读更舒服\r\n- 微信账号绑定相关提示文案和界面样式调整\r\n- 优化AI摘要重复内容，自动折叠冗余文字', 1, '2026-09-22 10:02:25', '2026-09-22 10:02:25'),
(7, '1.7.28', 1007, 'all', 0, 'https://mc.xzwmc.com/csgocs/', '- 新增系统维护检测：平台维护时会自动展示维护提示页面\r\n- 开屏广告支持随机轮播，配置多条广告时会随机展示其中一条\r\n- 公告编辑器升级，支持 Markdown 排版，发布前可以预览效果\r\n- 新增统一客服入口，在多处页面都可以快速联系客服\r\n- 增加一键清理本地缓存功能，释放手机存储空间\r\n- 课程推送、成绩消息推送设置页面重新改版，布局更清晰\r\n- 电费相关说明文案优化，更容易看懂\r\n- 轮播图可以分别给小程序、App、网页设置不同跳转链接\r\n- 修复隐私页面客服按钮在App端显示异常问题\r\n- 优化剪贴板复制失败的提示处理', 1, '2026-09-22 10:03:00', '2026-09-22 14:41:57'),
(8, '1.9.1', 1901, 'all', 0, 'https://xiaolong666.lanzoub.com/iaaRh49inxyh&pwd=55cx', '- 上线【协议中心】，集中存放隐私政策、用户服务协议等全部官方文档，随时查看\r\n- 账号注销流程升级，协议可由后台灵活管理，体验更合规顺畅\r\n- AI助手能力升级，优化回答规范，教务相关查询结果展示更清晰\r\n- 宿舍用电页面新增记录筛选，余额实时展示，查电费更方便\r\n- 应用更新弹窗升级，支持多种下载渠道，附带下载密码提示\r\n- 修复电费记录筛选异常问题\r\n- 修复成绩查询偶发逻辑错误\r\n- 统一小程序 / App 协议页面样式，多端浏览效果保持一致', 1, '2026-09-22 10:03:33', '2026-09-23 15:26:26'),
(9, '2.0', 2000, 'all', 0, 'https://xiaolong666.lanzoub.com/iaaRh49inxyh&pwd=55cx', '本版本更新为重要功能更新，请及时更新\r\n- 全线新增图片人机验证，提升账号登录、注册、改密、注销安全性\r\n- 首页新增日期、教学周展示，校园信息更直观\r\n- 电费页面支持时间正序/倒序排序，方便查看历史账单\r\n- 新增首页浮动刷新按钮，一键刷新首页数据\r\n- 公告页新增联系客服弹窗，问题反馈更便捷\r\n- （重要）支持 URL Scheme 唤起App、网页端登录完成自动唤醒App\r\n- 统一全站表单校验、输入规范，注册、改密、发邮件、注销流程更稳定\r\n- 优化验证码加载、回传逻辑，新增兜底轮询，大幅减少验证失败情况\r\n- 优化课程表作息时间适配，适配更多作息模板\r\n- 优化注销协议展示、页面文案与整体UI样式，界面更整洁\r\n- 优化全局登录提示逻辑：首页可免登录浏览，点击功能再弹窗提醒\r\n- 切换为正式版服务器接口，整体速度、稳定性提升\r\n- 优化App下载链接获取逻辑，解决链接过期失效问题\r\n- 完善版本更新弹窗提示、下载、安装容错机制\r\n- 协议、公告、详情页全部升级富文本渲染，排版更美观、阅读更清晰', 0, '2026-09-22 14:42:42', '2026-10-10 09:05:27'),
(10, '1.9.3', 1903, 'all', 0, 'https://xiaolong666.lanzoub.com/iaaRh49inxyh&pwd=55cx', '本版本更新为重要功能更新，请及时更新\r\n- 全线新增图片人机验证，提升账号登录、注册、改密、注销安全性\r\n- 首页新增日期、教学周展示，校园信息更直观\r\n- 电费页面支持时间正序/倒序排序，方便查看历史账单\r\n- 新增首页浮动刷新按钮，一键刷新首页数据\r\n- 公告页新增联系客服弹窗，问题反馈更便捷\r\n- （重要）支持 URL Scheme 唤起App、网页端登录完成自动唤醒App\r\n- 统一全站表单校验、输入规范，注册、改密、发邮件、注销流程更稳定\r\n- 优化验证码加载、回传逻辑，新增兜底轮询，大幅减少验证失败情况\r\n- 优化课程表作息时间适配，适配更多作息模板\r\n- 优化注销协议展示、页面文案与整体UI样式，界面更整洁\r\n- 优化全局登录提示逻辑：首页可免登录浏览，点击功能再弹窗提醒\r\n- 切换为正式版服务器接口，整体速度、稳定性提升\r\n- 优化App下载链接获取逻辑，解决链接过期失效问题\r\n- 完善版本更新弹窗提示、下载、安装容错机制\r\n- 协议、公告、详情页全部升级富文本渲染，排版更美观、阅读更清晰', 1, '2026-09-23 15:22:27', '2026-09-23 15:34:18'),
(11, '1.9.5', 1905, 'all', 0, 'https://xiaolong666.lanzoub.com/iaaRh49inxyh&pwd=55cx', '优化AI分析提示文案并新增Tab点击刷新功能\r\n更新多页面AI加载提示文案，补充过程说明\r\n新增底部导航Tab点击刷新页面数据的功能\r\n调整课程表周次选择逻辑，选择后自动加载课程\r\n优化AI接口错误提示，统一引导联系客服\r\n新增教务账号未绑定空态与折线图组件，统一日期格式\r\n新增教务功能未绑定账号空态，提供前往绑定按钮\r\n统一全端日期时间格式为 YYYY/M/D HH:mm\r\n新增小时级用电数据提示，区分整晚合计数据\r\n调整首页菜单文本，优化教务相关页面交互\r\n完善小程序和 App 端的反馈提交人机验证逻辑，区分小程序端和其他端的验证方式\r\n调整反馈提交接口的校验逻辑\r\n优化宿舍电费查询逻辑，现在支持茂名校区11-13区、高州校区电费查询了\r\n修复电费折算逻辑，仅在余额单位为度时进行电量折算\r\n优化联系客服弹窗关闭后的页面跳转逻辑', 1, '2026-10-05 12:57:14', '2026-10-05 12:57:14');

