--
-- 表的结构 `nteam_config`
--

CREATE TABLE `nteam_config` (
  `id` int(11) NOT NULL,
  `SiteName` varchar(255) NOT NULL COMMENT '网站名称',
  `Name` varchar(255) NOT NULL COMMENT '网站简称',
  `Descriptison` varchar(255) NOT NULL COMMENT '网站描述',
  `Keywords` varchar(255) NOT NULL COMMENT '网站关键词',
  `ICP` varchar(255) NOT NULL COMMENT 'ICP备案号',
  `Url` varchar(255) NOT NULL COMMENT '网址',
  `Index_Image` varchar(255) NOT NULL COMMENT '首页背景图',
  `Mail_Smtp` varchar(255) NOT NULL COMMENT 'SMTP地址',
  `Mail_Port` varchar(255) NOT NULL COMMENT 'SMTP端口',
  `Mail_Name` varchar(255) NOT NULL COMMENT '邮箱账号',
  `Mail_Pwd` varchar(255) NOT NULL COMMENT '邮箱密码（授权码）',
  `Mail_Secure` varchar(10) DEFAULT 'ssl' COMMENT '安全协议:ssl,tls,none',
  `Mail_Admin_Emails` text COMMENT '管理员接收邮箱地址，多个用逗号分隔',
  `Mail_Same_Email_Interval` int(11) DEFAULT '60' COMMENT '同一邮箱最小发送间隔（秒）',
  `Mail_Platform_Per_Minute` int(11) DEFAULT '10' COMMENT '平台1分钟内最多发送邮件数',
  `Captcha_Open` int(1) DEFAULT '1' COMMENT '是否启用人机验证',
  `hCaptcha_Sitekey` varchar(255) DEFAULT '' COMMENT 'hCaptcha Site Key',
  `Index_Fang` int(11) DEFAULT NULL COMMENT '防止xxs扒站JS开关',
  `Jump` int(11) DEFAULT NULL COMMENT 'QQVX打开提示跳转',
  `hCaptcha_Secretkey` varchar(255) DEFAULT 'ES_e8d2..' COMMENT 'hCaptcha Secret Key',
  `Mail_Site_Url` text COMMENT '邮件配置',
  `cookiebox_login` text COMMENT '邮件配置',
  `AI_Token` text COMMENT '邮件配置',
  `AI_BaseURL` text COMMENT '邮件配置',
  `AI_Model` text COMMENT '邮件配置',
  `Cancel_Enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '注销功能总开关 0关 1开',
  `Cancel_Verify_Mode` varchar(20) NOT NULL DEFAULT 'password' COMMENT '验证方式 password/email/password_email',
  `Cancel_Cooling_Enable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '冷静期开关 0关 1开',
  `Cancel_Cooling_Days` int(11) NOT NULL DEFAULT '10' COMMENT '冷静期天数（1-90）',
  `Cancel_Mail_Submit` tinyint(1) NOT NULL DEFAULT '1' COMMENT '提交注销时是否发送通知邮件',
  `Cancel_Mail_Deleted` tinyint(1) NOT NULL DEFAULT '1' COMMENT '注销成功时是否发送通知邮件',
  `Cancel_Mail_Revoked` tinyint(1) NOT NULL DEFAULT '1' COMMENT '注销申请被自动撤销时是否发送通知邮件',
  `splash_enabled` text COMMENT '邮件配置',
  `app_update_enabled` text COMMENT '邮件配置',
  `Maintenance_Start` varchar(5) NOT NULL DEFAULT '' COMMENT '每日维护开始时间（HH:MM，留空=沿用旧配置）',
  `Maintenance_End` varchar(5) NOT NULL DEFAULT '' COMMENT '每日维护结束时间（HH:MM，留空=沿用旧配置）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

