--
-- 表的结构 `nteam_contact_msgs`
--

CREATE TABLE `nteam_contact_msgs` (
  `id` int(11) NOT NULL,
  `name` varchar(64) NOT NULL DEFAULT '' COMMENT '姓名',
  `phone` varchar(32) NOT NULL DEFAULT '' COMMENT '手机',
  `email` varchar(128) NOT NULL DEFAULT '' COMMENT '邮箱',
  `subject` varchar(255) NOT NULL DEFAULT '' COMMENT '主题',
  `content` text COMMENT '留言内容',
  `ip` varchar(64) NOT NULL DEFAULT '' COMMENT '提交 IP',
  `ua` varchar(255) NOT NULL DEFAULT '' COMMENT 'User-Agent',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0未读 1已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联用户ID（0=官网访客）',
  `source` varchar(16) NOT NULL DEFAULT 'site' COMMENT '来源：site=官网，user=用户端',
  `handle_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '处理状态：0待处理 1处理中 2已解决 3已驳回 4已忽略',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '处理备注（用户端可见）',
  `update_time` datetime DEFAULT NULL COMMENT '状态最后更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='官网联系我们留言';

