--
-- 表的结构 `nteam_feature_settings`
--

CREATE TABLE `nteam_feature_settings` (
  `id` int(11) NOT NULL,
  `feature_key` varchar(50) NOT NULL COMMENT '功能标识',
  `feature_name` varchar(100) NOT NULL COMMENT '功能名称',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用 1启用 0禁用',
  `announcement` text COMMENT '公告内容',
  `announcement_type` varchar(20) DEFAULT 'info' COMMENT '公告类型 info/success/warning/danger',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `follow_global` tinyint(1) NOT NULL DEFAULT '1' COMMENT '公告是否跟随总开关：1=跟随，0=不跟随',
  `disabled_action` varchar(32) NOT NULL DEFAULT 'redirect' COMMENT '功能未启用时的处理方式（小程序端AI对话专用）：mask=展示遮罩，redirect=跳转用电统计页'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='功能设置表';

