--
-- 表的结构 `nteam_grade_push_records`
--

CREATE TABLE `nteam_grade_push_records` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `course_id` varchar(100) NOT NULL COMMENT '课程编号ID（唯一标识）',
  `course_name` varchar(200) DEFAULT NULL COMMENT '课程名称',
  `score` varchar(20) DEFAULT NULL COMMENT '成绩',
  `credit` decimal(5,1) DEFAULT NULL COMMENT '学分',
  `semester` varchar(50) DEFAULT NULL COMMENT '学期',
  `push_type` varchar(20) NOT NULL COMMENT '推送类型：wechat,email',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态：1已推送,2推送失败',
  `error_msg` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `pushed_at` datetime DEFAULT NULL COMMENT '推送时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='成绩推送记录表';

