--
-- 表的结构 `nteam_home_faq`
--

CREATE TABLE `nteam_home_faq` (
  `id` int(11) NOT NULL,
  `category` varchar(64) NOT NULL DEFAULT '常见问题' COMMENT '分类',
  `question` varchar(255) NOT NULL DEFAULT '' COMMENT '问题',
  `answer` text COMMENT '答案（支持简单 HTML）',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（小在前）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1显示 0隐藏',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='官网常见问题';

--
-- 转存表中的数据 `nteam_home_faq`
--

INSERT INTO `nteam_home_faq` (`id`, `category`, `question`, `answer`, `sort`, `status`, `create_time`, `update_time`) VALUES
(1, '常见问题', '智校通提供哪些校园服务？', '智校通覆盖校园生活全场景：教务查询（课表、成绩、考试、空教室）、生活服务（电费查询、报修、失物招领）、宿舍管理（归寝统计、住宿调整、访客管理）、资讯通知，以及基于大模型的校园 AI 助手，师生扫码即用。', 0, 1, '2026-09-18 16:20:21', NULL),
(2, '常见问题', '如何查询课表、成绩和考试安排？', '登录微信小程序或 App 后进入「教务服务」，即可一键查询本学期课表、历史成绩、考试安排与空教室，App 还支持离线课表，无网络也能随时查看。', 0, 1, '2026-09-18 16:20:44', NULL),
(3, '常见问题', '校园 AI 助手能帮我做什么？', '内置基于大模型的校园 AI 助手，可解答校规校纪、办事流程、校园导航等问题，还能结合你的课表、成绩、电费等个人数据，提供个性化的提醒与办事建议，7×24 小时在线。', 0, 1, '2026-09-18 16:21:08', NULL),
(4, '安全隐私', '我的个人信息和数据安全吗？', '我们严格遵循《个人信息保护法》，数据全程加密存储与传输，按最小权限原则分配角色，操作全程留痕可审计；敏感信息仅用于提供服务所需，绝不违规外泄。', 0, 1, '2026-09-18 16:21:30', '2026-09-18 16:27:10'),
(5, '常见问题', '支持哪些通知方式？', '支持 App 推送、微信模板消息与短信通知，停水停电、紧急事件等重要事项可一键群发，确保信息及时触达。', 0, 1, '2026-09-18 16:21:58', NULL),
(6, '常见问题', '智校通支持哪些登录方式？', '支持学校统一身份认证（CAS / OAuth），师生首次使用即可快速绑定校园账号，无需重复注册。', 0, 1, '2026-09-18 16:22:31', NULL),
(7, '常见问题', '忘记密码或无法登录怎么办？', '可通过学校统一认证找回密码，或在登录页点击「找回密码」由自行重置。', 0, 1, '2026-09-18 16:23:05', NULL),
(8, '常见问题', '一个账号可以在多台设备登录吗？', '默认支持手机、平板与 Web 同时在线；若学校出于安全考虑需要限制共用，可能会有单设备或多设备登录策略。', 0, 1, '2026-09-18 16:23:31', NULL),
(9, '技术支持', '数据如何与学校现有系统对接？', '提供开放 API 与标准数据接口，可与教务系统、一卡通、宿舍管理系统等对接，支持定时同步与实时回调，平滑融入既有信息化架构。', 0, 1, '2026-09-18 16:23:58', NULL),
(10, '技术支持', '系统稳定性如何保障？', ' 采用多节点容灾、7×24 小时监控与自动告警机制，提供 SLA 可用性保障，并针对重大故障制定应急响应预案。', 0, 1, '2026-09-18 16:24:20', NULL),
(11, '技术支持', '支持私有化 / 本地化部署吗？', '支持。可部署到学校自有服务器或教育专有云，满足数据不出校、自主可控的合规要求，并提供配套运维指引。', 0, 1, '2026-09-18 16:24:42', NULL),
(12, '技术支持', '提供哪些运维支持？', '提供在线帮助文档、工单系统、专属客户成功经理与定期回访，确保系统平稳运行，问题得到及时响应。', 0, 1, '2026-09-18 16:25:04', NULL),
(13, '技术支持', '如何获取培训与对接文档？', '开通后提供管理员手册、对接 API 文档与视频教程，并支持到校培训与远程答疑，帮助第三方运营商快速上手并深度使用。', 0, 1, '2026-09-18 16:25:26', '2026-09-18 16:25:39'),
(14, '安全隐私', '数据存储在哪里？', '数据部署于国内合规云节点，符合《个人信息保护法》与教育行业数据管理要求，支持私有化部署满足数据不出校。', 0, 1, '2026-09-18 16:27:53', NULL),
(15, '安全隐私', '如何防止账号被盗用？', '支持设备绑定、异地登录提醒与登录风控，异常登录需二次验证；管理员可一键下线可疑会话，及时止损。', 0, 1, '2026-09-18 16:28:21', NULL),
(16, '安全隐私', '智校通如何保护我的隐私？', ' 遵循最小化采集原则，仅收集提供服务所必需的信息；数据按角色脱敏展示，未经授权不得访问，详细做法见《隐私政策》。', 0, 1, '2026-09-18 16:28:44', NULL);

