--
-- 表的结构 `nteam_mail_log`
--

CREATE TABLE `nteam_mail_log` (
  `id` int(11) NOT NULL,
  `to_email` varchar(255) NOT NULL COMMENT '接收邮箱',
  `subject` varchar(500) NOT NULL COMMENT '邮件主题',
  `content` text COMMENT '邮件内容摘要',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:0失败,1成功',
  `error_msg` text COMMENT '错误信息',
  `ip` varchar(50) DEFAULT NULL COMMENT '发送IP',
  `create_time` datetime NOT NULL COMMENT '发送时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邮件发送日志表';

