--
-- 表的结构 `nteam_power_daily_records`
--

CREATE TABLE `nteam_power_daily_records` (
  `id` int(11) NOT NULL,
  `room_num` varchar(50) NOT NULL COMMENT '宿舍编号',
  `record_time` datetime DEFAULT NULL COMMENT '记录时间',
  `record_date` date NOT NULL COMMENT '记录日期',
  `balance` decimal(10,2) NOT NULL COMMENT '当日余额',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用电记录表';

