--
-- 表的结构 `nteam_wx_templates`
--

CREATE TABLE `nteam_wx_templates` (
  `id` int(11) NOT NULL,
  `template_id` varchar(64) NOT NULL COMMENT '模板ID',
  `scene_type` varchar(50) DEFAULT NULL COMMENT '模板场景类型：schedule_reminder-课程提醒, grade_notify-成绩通知, power_fee-电费提醒, power_report-电费报告',
  `name` varchar(100) NOT NULL COMMENT '模板名称',
  `description` varchar(255) DEFAULT NULL COMMENT '模板描述',
  `fields` text COMMENT '模板字段配置JSON',
  `default_data` text COMMENT '默认消息数据JSON',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='微信订阅消息模板配置表';

